<template><view class="page">
  <view class="between"><view><text class="eyebrow">DOUDOU · DAILY WORKSPACE</text><view class="title">把日常，打理好。</view></view><view class="avatar" @tap="go('/pages/profile/index')">豆</view></view>
  <view class="store-line"><text class="store-dot"/>{{ user.storeName }}<text class="muted"> · {{ today }}</text></view>
  <view v-if="isDemo" class="demo-banner">演示环境 · 数据保存在本机，未连接 CMP5</view>
  <view class="hero"><view><text class="hero-label">今日门店待办</text><view class="hero-number">{{ stats.pending + stats.differences }}<text>项待处理</text></view><text class="hero-caption">及时收货与核对，让每一笔库存都有据可依。</text></view><view class="hero-art"><view class="box-top"/><view class="box-front"><text>豆豆</text></view><view class="small-leaf"/></view><button class="hero-button" @tap="open('receipts')">去处理收货 →</button></view>
  <view class="stats-grid"><view class="stat" @tap="open('orders')"><text class="status-number">{{ stats.orders }}</text><text class="muted">订货待审核</text></view><view class="stat" @tap="open('receipts')"><text class="status-number">{{ stats.pending }}</text><text class="muted">待确认收货</text></view><view class="stat" @tap="open('differences')"><text class="status-number amber">{{ stats.differences }}</text><text class="muted">待核对差异</text></view></view>
  <view class="between"><view class="section-title">门店业务</view><text class="muted">日常工作，一站完成</text></view>
  <view class="entry-grid"><view v-for="entry in entries" :key="entry.kind" class="entry card" @tap="entry.kind === 'create' ? go('/pages/create/index') : open(entry.kind)"><view :class="['entry-icon', entry.color]">{{ entry.icon }}</view><view class="entry-title">{{ entry.title }}<text>↗</text></view><text class="muted">{{ entry.desc }}</text></view></view>
  <view class="between"><view class="section-title">待收货配送</view><text class="link" @tap="open('receipts')">查看全部 →</text></view>
  <view v-if="error" class="error" @tap="load">{{ error }} · 点击重试</view><view v-if="loading" class="empty">正在加载门店数据…</view>
  <view v-for="doc in pending" :key="doc.id" class="card" @tap="go(`/pages/detail/index?kind=receipts&id=${doc.id}`)"><view class="between"><text class="product-name">华东配送中心</text><text class="tag pending">待收货</text></view><view class="muted" style="margin-top:12rpx">{{ doc.id }}</view><view class="divider"/><view class="between"><text class="muted">{{ doc.lines.length }} 种商品 · 来源 {{ doc.sourceId }}</text><text class="link">核对收货 →</text></view></view>
  <view v-if="!loading && !error && !pending.length" class="card empty">今日待收货已全部处理</view>
  <view class="footnote">认真做好每一件小事，生意自然有声有色。</view><BottomNav active="home"/>
</view></template>
<script setup>
import { ref, computed } from 'vue'
import { onShow, onPullDownRefresh } from '@dcloudio/uni-app'
import { api, client, guard, go, isDemo } from '../../services/api.js'
import BottomNav from '../../components/BottomNav.vue'
const stats = ref({ pending: 0, differences: 0, orders: 0, returns: 0 }), pending = ref([]), loading = ref(false), error = ref('')
const user = computed(() => client.getSession()?.user || {}), today = `${new Date().getMonth()+1}月${new Date().getDate()}日`
const entries = [{ kind: 'create', title: '门店订货', desc: '选好商品，及时补货', icon: '＋', color: 'mint' }, { kind: 'receipts', title: '收货确认', desc: '逐项核对，安心入库', icon: '↓', color: 'blue' }, { kind: 'differences', title: '差异核对', desc: '有差必查，有据可依', icon: '≠', color: 'sand' }, { kind: 'returns', title: '退货申请', desc: '规范退货，全程跟踪', icon: '↗', color: 'rose' }]
const open = kind => go(`/pages/orders/index?kind=${kind}`)
async function load() { if (!guard()) return; loading.value = true; error.value = ''; try { const [s, receipts] = await Promise.all([api.get('/dashboard'), api.get('/receipts')]); stats.value = s; pending.value = receipts.filter(x => x.status === 'PENDING').slice(0, 3) } catch(e) { error.value = e.message } finally { loading.value = false; uni.stopPullDownRefresh() } }
onShow(load); onPullDownRefresh(load)
</script>
<style scoped>
.avatar{background:#e0e9d8;border-radius:20rpx;width:72rpx;height:72rpx;display:flex;align-items:center;justify-content:center;font-size:35rpx;color:#41714c}.store-line{font-size:24rpx;margin-top:20rpx;display:flex;align-items:center;flex-wrap:wrap}.store-dot{width:12rpx;height:12rpx;border-radius:50%;background:#387651;margin-right:12rpx}.hero{position:relative;padding:34rpx;background:#286b50;border-radius:28rpx;color:white;overflow:hidden;min-height:300rpx}.hero-label{font-size:25rpx;color:#d1dfcc}.hero-number{font-size:80rpx;font-weight:650;line-height:1.4}.hero-number text{font-size:25rpx;margin-left:17rpx;font-weight:400}.hero-caption{display:block;color:#c6d9c6;font-size:21rpx;max-width:400rpx}.hero-button{background:#e6edcf;color:#2d5e45;font-size:24rpx;padding:16rpx 23rpx;margin-top:24rpx;display:inline-block;border-radius:12rpx}.hero-art{position:absolute;width:150rpx;height:165rpx;right:27rpx;top:40rpx;transform:rotate(-8deg)}.box-front{position:absolute;bottom:0;width:138rpx;height:105rpx;background:#c1ce94;border-radius:5rpx 5rpx 15rpx 15rpx;display:flex;align-items:center;justify-content:center;color:#5b7947;font-size:26rpx;box-shadow:10rpx 13rpx 0 #1c594350}.box-top{position:absolute;top:30rpx;left:-7rpx;width:152rpx;height:33rpx;border-radius:6rpx;background:#d5dfb3}.small-leaf{position:absolute;top:0;left:66rpx;width:45rpx;height:42rpx;background:#8cac73;border-radius:0 40rpx 0 40rpx}.stats-grid{display:grid;grid-template-columns:repeat(3,1fr);background:white;border:1rpx solid #e5ebe1;border-radius:24rpx;margin-top:20rpx;padding:28rpx 0}.stat{display:flex;align-items:center;flex-direction:column;gap:10rpx;border-right:1rpx solid #edf0e9}.stat:last-child{border-right:0}.amber{color:#ac8541}.entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:18rpx}.entry{margin-bottom:0}.entry-icon{width:66rpx;height:66rpx;border-radius:17rpx;font-size:39rpx;display:flex;align-items:center;justify-content:center}.entry-title{font-size:30rpx;font-weight:650;display:flex;justify-content:space-between;margin:20rpx 0 6rpx}.entry-title text{color:#a6b3a3;font-size:24rpx}.entry .muted{font-size:22rpx}.footnote{font-size:21rpx;color:#a4ad9d;text-align:center;margin-top:36rpx}
</style>
